from __future__ import annotations

import asyncio
import logging
import pathlib
import re
import time
from contextlib import asynccontextmanager
from datetime import datetime
from typing import AsyncIterator

import attr
from taf.config.testline.testline import TestLine  # type: ignore[import-untyped]
from taf.gnb.oam.coam.vdu import vdu as taf_admin_vdu  # type: ignore[import-untyped]
from taf.transport.ssh import ssh  # type: ignore[import-untyped]
from urllib3.exceptions import MaxRetryError  # type: ignore[import-untyped]

from taf.ul.ue.sim.env_setup.devices.device import Device
from taf.ul.ue.sim.env_setup.utils.exceptions import (
    ActivateException,
    OperationStateException,
    ResetException,
    RmodDetectionTimeout,
    UploadException,
    ValidateException,
)
from taf.ul.ue.sim.env_setup.utils.scfc_utils import copy_scfc_to_output_dir, get_dict_from_xml, save_dict_to_xml
from taf.ul.ue.sim.env_setup.utils.tools import is_path_the_same

RNICMODS_MO_REGEX = re.compile(r"RNICMOD-\d+$")


@attr.s(cmp=False, hash=True)
class VDU(Device):
    idx = attr.ib(type=int)
    configuration = attr.ib(type=TestLine, hash=False)
    bts_id = attr.ib(type=str)
    remote_host = attr.ib(type=str)
    output_directory_path = attr.ib(type=pathlib.Path)
    config_type = attr.ib(type=str)
    _user_flags = attr.ib(type=dict, hash=False)
    name = attr.ib(default="vdu", type=str, init=False)
    suite_config_dir = attr.ib(default="", type=str, init=False)
    scfc_name = attr.ib(default=None, type=pathlib.Path, init=False)
    _port = attr.ib(default="443", type=str, init=False)
    _user = attr.ib(default="Nemuadmin", type=str, init=False)
    _password = attr.ib(default="Nokia@123", type=str, init=False)
    _vdu_version = attr.ib(default=None, type=str, init=False)

    def __attrs_post_init__(self):
        self._port = self.configuration.oam_http_connection_details.port
        self._user = self.configuration.oam_http_connection_details.username
        # self._password = self.configuration.oam_http_connection_details.password
        self.remote_host = self.remote_host or "localhost"
        self.logger.info(f"Created {self}")

    def _get_taf_pdu_config(self):
        raise NotImplementedError

    def _get_lmp_ip_for_ute(self) -> str:
        raise NotImplementedError

    def _get_lmp_ip_for_taf(self) -> str:
        return self.configuration.oam_http_connection_details.addr

    def _get_lmp_password(self) -> str:
        return "Nokia@123"

    @property
    def targetbd(self):
        return asyncio.run(self._get_targetbd())

    async def _get_targetbd(self):
        alias = self._create_alias("k8s_conn")
        conn_details = await self._get_k8s_connection_details()
        namespace = self.configuration.cloud_deployment.cloud_hosting.namespace
        async with get_ssh_connection(conn_details.ip_addr, conn_details.username, conn_details.password, alias, self.logger) as k8s_conn:
            ret = await asyncio.to_thread(
                k8s_conn.execute,
                f"kubectl -n {namespace} exec -it ute-{namespace}-oamfh-0 -c "
                f"ctr-{namespace}-oamfh -- ls /ffs/run/RFSW | grep TargetBD_v | grep CNF",
                connection=alias,
            )
            targetbd_name = ret.strip()
            from_path = f"/ffs/run/RFSW/{targetbd_name}"
            remote_dest_path = f"/tmp/{targetbd_name}"
            local_dst_path = self.output_directory_path.joinpath(targetbd_name)
            await asyncio.to_thread(
                k8s_conn.execute,
                f"kubectl -n {namespace} exec -it ute-{namespace}-oamfh-0 -c " f"ctr-{namespace}-oamfh -- cat {from_path} > {remote_dest_path}",
                connection=alias,
            )
            await asyncio.to_thread(k8s_conn.download_file, remote_dest_path, local_dst_path, connection=alias)
        return local_dst_path

    async def _get_k8s_connection_details(self):
        return self.configuration.cloud_deployment.cloud_hosting.master_node.k8s_connection_details

    async def configure(self) -> None:
        if self.scfc_name:
            await self._prepare_scfc()
            await self._perform_full_commissioning(self._user_flags.get("cloud_bts_recovery", True))
        else:
            self.logger.info("No SCFC provided. Configuration skipped.")

    async def _prepare_scfc(self):
        await self._copy_and_save_scfc()
        if not self.scfc_name.name.startswith("MODIFIED"):
            await self._configure_rnicmods()

    async def wait_for_rmods_up(self, timeout: float) -> None:
        alias = self._create_alias("wait_for_rmods")
        start_time = time.time()
        async with get_vdu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._vdu_version, self.logger) as vdu_admin:
            while (time.time() - start_time) < timeout:
                try:
                    rmods_summary = await asyncio.to_thread(vdu_admin.get_rmods_summary, vdu_connection=alias)
                    self.logger.debug(f"RMODs summary: {rmods_summary['operational_state']}")
                    if int(rmods_summary["operational_state"]["disabled"]) == 0 and int(rmods_summary["operational_state"]["enabled"] >= 1):
                        self.logger.info("All RMODs enabled")
                        return
                except Exception as err:
                    self.logger.debug(err)
                await asyncio.sleep(10)
            raise RmodDetectionTimeout("RMODs not detected in time.")

    async def verify_all_is_up(self, timeout):
        alias = self._create_alias("wait_for_rmods")
        start_time = time.time()
        async with get_vdu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._vdu_version, self.logger) as vdu_admin:
            while (time.time() - start_time) < timeout:
                try:
                    vdu_state = await asyncio.to_thread(vdu_admin.get_vdu_state_data, vdu_connection=alias)
                    assert (op_state := vdu_state["operational_state"]) == "onAir", f"vDU is in state '{op_state}', expected: 'onAir'"
                    self.logger.info("vDU operational state is 'onAir'")
                    return
                except AssertionError as err:
                    self.logger.debug(err)
                    await asyncio.sleep(5)
                except Exception as err:
                    self.logger.debug(err, exc_info=True)
            raise OperationStateException("vDU is not in 'onAir' state.")

    async def _perform_full_commissioning(self, recovery: bool):
        try:
            return await self.__perform_full_commissioning()
        except Exception as err:
            self.logger.debug(f"{type(err)}, {err = }")
            if not recovery:
                raise
            self.logger.debug(err)
            self.logger_recovery.info(err)
            await self._get_recovery_snapshot()
            await self._recovery_for_commissioning(str(err))
            return await self.__perform_full_commissioning()

    async def __perform_full_commissioning(self, timeout: float = 600):
        alias = f"full_commissioning_{datetime.now()}_{self.lmp_ip}"
        async with get_vdu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._vdu_version, self.logger) as vdu_admin:
            plan_id = await self.upload(vdu_admin, alias, timeout)
            await self.validate(vdu_admin, alias, plan_id, timeout)
            await self.activate(vdu_admin, alias, plan_id, timeout)

    async def upload(self, vdu_admin: taf_admin_vdu, alias: str, timeout: float) -> str:
        start_time = time.time()
        ret = await asyncio.to_thread(vdu_admin.upload_plan, self.scfc_name.as_posix(), vdu_connection=alias)
        action_id = ret["action_id"]
        while (time.time() - start_time) < timeout:
            op_state = await asyncio.to_thread(vdu_admin.get_upload_plan_operation_status, action_id, vdu_connection=alias)
            self.logger.debug(f"UPLOAD: {op_state}")
            if (status := op_state["status"]) == "ongoing":
                pass
            elif status == "success":
                return ret["plan_id"]
            elif status == "failure":
                break
            else:
                self.logger.warning("Unexpected state.")
            await asyncio.sleep(1)
        raise UploadException(f"Upload failed after {time.time() - start_time}s. Timeout: {timeout}")

    async def validate(self, vdu_admin: taf_admin_vdu, alias: str, plan_id: str, timeout: float) -> None:
        start_time = time.time()
        ret = await asyncio.to_thread(vdu_admin.validate_plan, plan_id, vdu_connection=alias)
        action_id = ret["action_id"]
        while (time.time() - start_time) < timeout:
            op_state = await asyncio.to_thread(vdu_admin.get_validate_plan_operation_status, plan_id, action_id, vdu_connection=alias)
            self.logger.debug(f"VALIDATE: {op_state}")
            if (status := op_state["status"]) == "ongoing":
                pass
            elif status == "success":
                return
            elif status == "failure":
                break
            else:
                self.logger.warning("Unexpected state.")
            await asyncio.sleep(1)
        raise ValidateException(f"Validation failed after {time.time() - start_time}s. Timeout: {timeout}")

    async def activate(self, vdu_admin: taf_admin_vdu, alias: str, plan_id: str, timeout: float) -> None:
        start_time = time.time()
        ret = await asyncio.to_thread(vdu_admin.activate_plan, plan_id, vdu_connection=alias)
        action_id = ret["id"]
        while (time.time() - start_time) < timeout:
            try:
                op_state = await asyncio.to_thread(vdu_admin.get_activate_plan_operation_status, plan_id, action_id, vdu_connection=alias)
                self.logger.debug(f"ACTIVATE {op_state}")
                if (status := op_state["status"]) == "ongoing":
                    pass
                elif status == "success":
                    return
                elif status == "failure":
                    break
                else:
                    self.logger.warning("Unexpected state.")
                await asyncio.sleep(5)
            except MaxRetryError:
                await asyncio.sleep(3)
            except Exception as err:
                if "Service Unavailable" in str(err):
                    self.logger.debug("vDU reset ongoing.")
                    await asyncio.sleep(30)
                else:
                    self.logger.debug(f"Activate Exc: {type(err)}, {err}")
                await asyncio.sleep(1)
        raise ActivateException(f"Activation failed after {time.time() - start_time}s. Timeout: {timeout}")

    async def _delete_all_plans(self, alias: str) -> None:
        async with get_vdu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._vdu_version, self.logger) as vdu_admin:
            await asyncio.gather(
                *[
                    self.__delete_plan(vdu_admin, plan, alias)
                    for plan in await asyncio.to_thread(vdu_admin.get_staged_plans_info_list, vdu_connection=alias)
                ]
            )
            assert len(await asyncio.to_thread(vdu_admin.get_staged_plans_info_list, vdu_connection=alias)) == 0

    async def __delete_plan(self, vdu_admin: taf_admin_vdu, plan: dict, alias: str) -> None:
        self.logger.debug(f"Removing plan: {plan}")
        await asyncio.to_thread(vdu_admin.delete_staged_plan_file, plan["plan_id"], vdu_connection=alias)
        self.logger.debug(f"Plan {plan} removed")

    async def _get_recovery_snapshot(self):
        if not self._user_flags.get("recovery_snapshot", False):
            self.logger.debug("Recovery snapshot disabled.")
            return
        alias = f"recovery_snapshot{datetime.now()}_{self.lmp_ip}"
        async with get_vdu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._vdu_version, self.logger) as vdu_admin:
            self.logger.debug("Trying to gather recovery snapshot")
            ret = await asyncio.to_thread(vdu_admin.get_local_snapshot, self.output_directory_path.as_posix(), vdu_connection=alias)
            self.logger.debug(f"Recovery snapshot gathered to {self.output_directory_path} as {ret}")

    async def _recovery_for_commissioning(self, err_msg: str) -> None:
        alias = f"recovery_for_commissioning_{datetime.now()}_{self.lmp_ip}"
        if "Insufficient Storage" in err_msg:
            await self._delete_all_plans(alias)
        await self._reset_via_admin(alias)

    async def _reset_via_admin(self, alias: str, timeout: float = 300) -> None:
        async with get_vdu_admin_connection(alias, self.lmp_ip, self._port, self._user, self._password, self._vdu_version, self.logger) as vdu_admin:
            start_time = time.time()
            ret = await asyncio.to_thread(vdu_admin.reset_vdu, vdu_connection=alias)
            self.logger.debug(f"{ret = }")
            operation_id = ret["id"]
            while (time.time() - start_time) < timeout:
                try:
                    op_state = await asyncio.to_thread(
                        vdu_admin.get_reset_vdu_operation_status,
                        operation_id=operation_id,
                        timeout=60,
                        vdu_connection=alias,
                    )
                    self.logger.debug(f"RESET: {op_state}")
                    if (status := op_state["status"]) == "ongoing":
                        pass
                    elif status == "success":
                        return
                    elif status == "failure":
                        break
                    else:
                        self.logger.warning("Unexpected state.")
                    await asyncio.sleep(5)
                except MaxRetryError:
                    await asyncio.sleep(5)
                except Exception as err:
                    if "Service Unavailable" in str(err):
                        self.logger.debug("vDU reset ongoing.")
                        await asyncio.sleep(30)
                    else:
                        self.logger.debug(f"Reset Exc: {type(err)}, {err}")
                    await asyncio.sleep(1)
            raise ResetException(f"Reset failed after {time.time() - start_time}s. Timeout: {timeout}")

    async def _configure_rnicmods(self) -> None:
        if not hasattr(self.configuration, "rannics") or len(self.configuration.rannics) == 0:
            self.logger.info("No RANNICs provided. Configuration skipped.")
            return
        scfc_data = get_dict_from_xml(self.scfc_name)
        rnics_mods = [_ for _ in scfc_data["raml"]["cmData"]["managedObject"] if RNICMODS_MO_REGEX.search(_["@distName"])]
        for idx, rnidmod in enumerate(rnics_mods):
            for p in rnidmod["p"]:
                if p["@name"] == "prodCodePlanned":
                    p["#text"] = f"{self.configuration.rannics[idx].product_code}"
                if p["@name"] == "serialNumberPlanned":
                    p["#text"] = f"{self.configuration.rannics[idx].serial_number}"
        self.scfc_name = self.scfc_name.with_name(f"MODIFIED_{self.scfc_name.name}")
        save_dict_to_xml(scfc_data, self.scfc_name)

    async def _copy_and_save_scfc(self):
        new_scfc_path = self.output_directory_path.joinpath(self.scfc_name.name)
        if not is_path_the_same(self.scfc_name, new_scfc_path, self.logger):
            await asyncio.to_thread(copy_scfc_to_output_dir, self.scfc_name, self.output_directory_path)
        self.scfc_name = new_scfc_path


@asynccontextmanager
async def get_vdu_admin_connection(
    alias: str, host: str, port: str, user: str, password: str, version: str | None, logger: logging.Logger
) -> AsyncIterator[taf_admin_vdu]:
    admin_vdu = taf_admin_vdu()
    try:
        logger.debug(f"SETUP START: vDU_ADMIN: [[{user}:{password}]@{host}:{port} -- {alias=}--{version=}]")
        if version is None:
            await asyncio.to_thread(admin_vdu.connect_to, host, port, user, password, secure=True, connection_name=alias)
        else:
            await asyncio.to_thread(
                admin_vdu.connect_to,
                host,
                port,
                user,
                password,
                vdu_version=version,
                secure=True,
                connection_name=alias,
            )
        logger.debug(f"SETUP DONE: vDU_ADMIN: [[{user}:{password}]@{host}:{port} -- {alias=}--{version=}]")
        yield admin_vdu
    finally:
        logger.debug(f"TEARDOWN START: vDU_ADMIN: [[{user}:{password}]@{host}:{port} -- {alias=}--{version=}]")
        try:
            await asyncio.to_thread(admin_vdu.disconnect, vdu_connection=alias)
        except Exception as err:
            logger.debug(err)
        logger.debug(f"TEARDOWN DONE: vDU_ADMIN: [[{user}:{password}]@{host}:{port} -- {alias=}--{version=}]")


@asynccontextmanager
async def get_ssh_connection(host: str, user: str, password: str, alias: str, logger: logging.Logger) -> AsyncIterator[ssh]:
    k8s_conn = ssh()
    try:
        logger.debug(f"SETUP START: vDU_K8S: [[{user}:{password}]@{host} -- {alias=}]")
        await asyncio.to_thread(k8s_conn.connect_to, host, user, password, alias=alias)
        logger.debug(f"SETUP DONE: vDU_K8S: [[{user}:{password}]@{host} -- {alias=}]")
        yield k8s_conn
    finally:
        try:
            logger.debug(f"TEARDOWN START: vDU_K8S: [[{user}:{password}]@{host} -- {alias=}]")
            await asyncio.to_thread(k8s_conn.disconnect, connection=alias)
        except Exception as err:
            logger.error(err)
        logger.debug(f"TEARDOWN DONE: vDU_K8S: [[{user}:{password}]@{host} -- {alias=}]")
